patches.after:
/* 本次仅增加：互斥阶段折叠、顶部键盘说明、已通过筛选。 */
.stage-toggle{display:inline-flex;align-items:center;gap:8px;padding:0;font:inherit;font-weight:inherit;color:inherit;text-align:left}
.stage-arrow{display:inline-block;width:12px;font-size:18px;line-height:1;transform:rotate(0deg)}
.stage-toggle[aria-expanded="true"] .stage-arrow{transform:rotate(90deg)}
.top .keys{display:block;position:relative;flex:none;padding:0;border:0}
.top-keys>summary{list-style:none;cursor:pointer}.top-keys>summary::-webkit-details-marker{display:none}
.keys-panel{position:absolute;right:0;top:calc(100% + 8px);z-index:30;width:220px;padding:14px;border:1px solid var(--line);border-radius:var(--r-sm);background:var(--surface)}
nav button[data-filter="passed"]{--st:var(--st-passed)}

</style>

/* 错误改弹窗：不占主区 tabs 上方。 */
.error-dialog[hidden]{display:none}
.error-dialog{position:fixed;inset:0;z-index:60;display:grid;place-items:center;padding:24px}
.error-dialog .drawer-mask{position:absolute;inset:0;background:oklch(20% 0.01 80 / .45)}
.error-panel{position:relative;z-index:1;width:min(720px,96vw);max-height:min(78vh,680px);background:var(--surface);border:1px solid var(--line);border-radius:var(--r-lg);box-shadow:0 24px 64px oklch(20% 0.01 80 / .22);display:flex;flex-direction:column;min-height:0}
.error-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;padding:14px 16px;border-bottom:1px solid var(--line);flex:none}
.error-head h2{margin:0;font:500 14px/1.2 var(--sans);color:var(--danger)}
.error-sub{margin:4px 0 0;font-size:12px;color:var(--muted)}
.error-body{margin:0;padding:14px 16px 16px;flex:1;min-height:0;overflow:auto;font:12px/1.55 var(--mono);color:var(--ink-2);white-space:pre-wrap;word-break:break-word}
.status.has-detail{cursor:pointer;text-decoration:underline;text-underline-offset:3px}
</style>
